insert into memes (title,slug,aliases,summary,description,origin,usage_note,caution,usage_context,usage_examples,safety_level,lifecycle_status,moderation_status,category,media_type,difficulty,sentiment,origin_year,korea_viral_year,year_precision,era_type,trend_score,published_at) values ('꼰대','꼰대','{꼰대짓,"젊은 꼰대",Kkondae,kkondae}'::text[],'자기 생각만 옳다며 가르치려 드는 사람을 낮춰 부르는 말','원래 학생들이 아버지나 선생님 같은 어른을 낮춰 부르던 은어다. 지금은 나이와 상관없이 권위적이고 자기 경험만 옳다며 남을 가르치려 드는 사람을 가리킨다. 그런 행동은 ''꼰대짓'', 젊은데도 그런 사람은 ''젊은 꼰대''라고 한다. 영국 BBC가 2019년 소셜미디어에서 ''오늘의 단어''로 소개하고 기사로도 다뤘을 만큼 한국 직장 문화를 보여 주는 말로 해외에도 알려졌다.','학생들이 어른을 부르던 오래된 은어가 2010년대 권위적인 사람 전체를 가리키는 말로 넓어짐','권위적인 행동을 비판하거나, 내가 그러지 않았는지 스스로 돌아볼 때 쓴다.','사람을 낮춰 부르는 말이라, 당사자 앞이나 직장에서 쓰면 다툼이 생길 수 있다.','{"sns": "yellow", "work": "red", "family": "yellow", "friends": "green"}'::jsonb,'[{"text": "방금 내가 한 말, 좀 꼰대 같았나?", "situation": "스스로 돌아볼 때"}, {"text": "그 선배 또 라떼 이야기 했어? 완전 꼰대네", "situation": "친구와 회사 이야기"}]'::jsonb,'yellow','active','approved','phrase','text','beginner','negative',null,2016,'unknown','social_media',39,now()) on conflict (slug) do nothing;
insert into memes (title,slug,aliases,summary,description,origin,usage_note,caution,usage_context,usage_examples,safety_level,lifecycle_status,moderation_status,category,media_type,difficulty,sentiment,origin_year,korea_viral_year,year_precision,era_type,trend_score,published_at) values ('꾸안꾸','꾸안꾸','{"꾸민 듯 안 꾸민 듯","꾸안꾸 룩",Kku-an-kku,Kkuankku}'::text[],'''꾸민 듯 안 꾸민 듯''의 줄임말','너무 힘주지 않았는데도 센스 있어 보이는 자연스러운 옷차림이나 화장을 말한다. 화려한 옷보다 단순한 옷으로 신경 쓴 듯한 느낌을 내는 것이 핵심이다. 처음에는 쇼핑몰과 잡지가 상품을 소개하려고 많이 쓴 말이었지만, 지금은 일상어가 됐다. 반대로 한껏 꾸민 모습은 ''꾸꾸꾸''라고 부른다.','2019년 후반부터 패션 쇼핑몰과 잡지, SNS에서 자연스러운 스타일을 부르는 말로 쓰이기 시작함','자연스럽게 멋 낸 옷차림을 칭찬하거나, 오늘 스타일을 소개할 때 쓴다.',NULL,'{"sns": "green", "work": "green", "family": "green", "friends": "green"}'::jsonb,'[{"text": "오늘 완전 꾸안꾸 느낌 좋다", "situation": "친구 옷을 칭찬할 때"}, {"text": "너무 차려입지 말고 꾸안꾸로 가자", "situation": "약속 전 옷 고를 때"}]'::jsonb,'green','active','approved','phrase','text','beginner','wholesome',2019,2019,'approximate','social_media',39,now()) on conflict (slug) do nothing;
insert into memes (title,slug,aliases,summary,description,origin,usage_note,caution,usage_context,usage_examples,safety_level,lifecycle_status,moderation_status,category,media_type,difficulty,sentiment,origin_year,korea_viral_year,year_precision,era_type,trend_score,published_at) values ('내 마음속에 저장','내-마음속에-저장','{저장,내마음속에저장,"윙크 저장","Saved in my heart"}'::text[],'너무 좋아서 마음에 담아 두겠다는 귀여운 표현','2017년 Mnet 오디션 예능 ''프로듀스 101 시즌2''에서 박지훈이 카메라를 보며 윙크하고 한 말로 유명해졌다. 이 장면이 크게 화제가 되면서 그는 ''윙크 남신''이라는 별명을 얻었다. 그 뒤 사람들은 마음에 드는 사진이나 순간을 보고 "내 마음속에 저장"이라고 쓰기 시작했다. 지금은 조금 옛날 유행어지만 귀엽게 좋아하는 마음을 표현할 때 여전히 쓴다.','2017년 Mnet 오디션 예능 프로듀스 101 시즌2에서 박지훈이 윙크하며 말한 방송 장면에서 시작','좋아하는 사진이나 순간을 보고 장난스럽게 쓴다. 윙크 이모티콘과 함께 쓰면 잘 어울린다.',NULL,'{"sns": "green", "work": "green", "family": "green", "friends": "green"}'::jsonb,'[{"text": "이건 내 마음속에 저장", "situation": "귀여운 강아지 사진을 보고"}, {"text": "이 사진 내 마음속에 저장했어", "situation": "친구가 잘 나온 사진을 보냈을 때"}]'::jsonb,'green','archived','approved','phrase','video','beginner','wholesome',2017,2017,'year','social_media',30,now()) on conflict (slug) do nothing;
insert into memes (title,slug,aliases,summary,description,origin,usage_note,caution,usage_context,usage_examples,safety_level,lifecycle_status,moderation_status,category,media_type,difficulty,sentiment,origin_year,korea_viral_year,year_precision,era_type,trend_score,published_at) values ('내돈내산','내돈내산','{"내 돈 주고 내가 산",#내돈내산,Nae-don-nae-san,Naedonnaesan}'::text[],'''내 돈 주고 내가 산'' 물건이라는 뜻, 협찬 아님을 밝히는 말','광고나 협찬 없이 자기 돈으로 산 물건을 리뷰할 때 붙이는 말이다. 인플루언서가 돈이나 제품을 받고 칭찬만 하는 리뷰가 늘자, 솔직한 리뷰라는 걸 보여 주려고 이 태그를 쓰기 시작했다. 영수증을 함께 보여 주기도 한다. 다만 태그만 붙이고 실제로는 광고비를 받는 경우도 있어 무조건 믿을 수는 없다.','2015년경 유튜버의 리뷰 영상에서 쓰이기 시작해, 협찬 리뷰에 대한 불신이 커진 2020년 무렵 널리 퍼짐','내가 직접 사서 써 본 물건을 소개할 때 쓴다. 리뷰를 볼 때 협찬인지 확인하는 기준으로도 쓴다.','실제로 광고를 받았다면 이 말을 쓰면 안 된다. 광고 표시를 숨기면 법에 걸릴 수 있다.','{"sns": "green", "work": "green", "family": "green", "friends": "green"}'::jsonb,'[{"text": "내돈내산 후기라 솔직하게 씁니다", "situation": "리뷰를 올릴 때"}, {"text": "이 이어폰 내돈내산인데 진짜 좋아", "situation": "친구에게 추천할 때"}]'::jsonb,'green','active','approved','phrase','text','beginner','wholesome',2015,2020,'approximate','social_media',41,now()) on conflict (slug) do nothing;
insert into memes (title,slug,aliases,summary,description,origin,usage_note,caution,usage_context,usage_examples,safety_level,lifecycle_status,moderation_status,category,media_type,difficulty,sentiment,origin_year,korea_viral_year,year_precision,era_type,trend_score,published_at) values ('뇌절','뇌절','{뇌절하다,"1절 2절 뇌절",Noe-jeol,Noejeol}'::text[],'같은 농담을 너무 반복해 분위기를 깨는 것','"1절만 해라"는 말에서 이어진 표현이다. 1절, 2절을 넘어 지나치게 같은 드립이나 행동을 이어 가 사람들을 지치게 하는 것을 뜻한다. 만화 ''나루토''에 나오는 기술 이름 ''뇌절''과 소리가 같아 붙은 말장난이다. 처음엔 재밌던 농담도 계속하면 뇌절이 된다는 식으로 쓰고, 유행어를 억지로 계속 쓰는 사람에게도 쓴다.','2019년 무렵 온라인 커뮤니티에서 ''1절, 2절, 3절''을 만화 나루토의 기술 이름 ''뇌절''로 비튼 말장난으로 퍼짐','친구의 과한 드립을 웃으며 멈추게 할 때 쓴다. 나 스스로 "이건 뇌절인가?"라고 돌아볼 때도 쓴다.','상대를 깎아내리는 말로 들릴 수 있다. 친한 사이에서만, 웃는 분위기에서 쓰자.','{"sns": "green", "work": "gray", "family": "yellow", "friends": "green"}'::jsonb,'[{"text": "그만해, 이제 뇌절이야", "situation": "같은 개그를 다섯 번째 할 때"}, {"text": "한 번 더 하면 뇌절이겠지?", "situation": "내가 드립을 또 치기 전에"}]'::jsonb,'yellow','cooling','approved','phrase','text','normal','ironic',2019,2019,'approximate','social_media',36,now()) on conflict (slug) do nothing;
insert into memes (title,slug,aliases,summary,description,origin,usage_note,caution,usage_context,usage_examples,safety_level,lifecycle_status,moderation_status,category,media_type,difficulty,sentiment,origin_year,korea_viral_year,year_precision,era_type,trend_score,published_at) values ('눈치','눈치','{Nunchi,nunchi,"눈치 보다","눈치 챙겨"}'::text[],'말하지 않아도 분위기와 마음을 알아채는 감각','다른 사람의 기분이나 그 자리의 분위기를 빠르게 알아채는 능력을 말한다. 한국 사람 사이의 관계에서 아주 중요하게 여겨지며, "눈치가 빠르다", "눈치 좀 챙겨"처럼 쓴다. 영어에는 딱 맞는 단어가 없어 감성 지능에 가깝다고 설명하고, 영어 위키백과에도 ''Nunchi''로 실려 있다. 한국 드라마와 직장 문화를 이해하는 데 꼭 필요한 말이다.','17세기 기록에도 나오는 오래된 한국어로, 2010년대 이후 해외에서 ''nunchi''라는 한국 문화 개념으로 소개됨','분위기를 잘 읽는 사람을 칭찬하거나, 눈치 없이 군 일을 농담으로 말할 때 쓴다.','"눈치 없다"는 말은 상대를 깎아내리는 말이 될 수 있다.','{"sns": "green", "work": "green", "family": "green", "friends": "green"}'::jsonb,'[{"text": "역시 눈치 빠르다", "situation": "친구가 분위기를 잘 맞췄을 때"}, {"text": "눈치 챙겨서 먼저 갈게", "situation": "둘만 있고 싶은 친구들을 보고"}]'::jsonb,'green','active','approved','phrase','text','normal','wholesome',null,null,'unknown',NULL,41,now()) on conflict (slug) do nothing;
insert into memes (title,slug,aliases,summary,description,origin,usage_note,caution,usage_context,usage_examples,safety_level,lifecycle_status,moderation_status,category,media_type,difficulty,sentiment,origin_year,korea_viral_year,year_precision,era_type,trend_score,published_at) values ('대박','대박','{"대박 사건",대박이다,Daebak,daebak}'::text[],'아주 크게 잘됐거나 놀라울 때 쓰는 말','무언가 크게 성공했거나 깜짝 놀랄 만큼 좋을 때 쓰는 말이다. "대박 났다", "대박 사건"처럼 쓰고, 그보다 조금 작으면 ''중박'', 크게 망하면 ''쪽박''이라고 한다. 도박에서 판돈보다 큰돈을 땄을 때 쓰던 말에서 왔다는 설이 유력하다. 영화가 크게 흥행했을 때 영화계에서 쓰던 말이 언론을 통해 퍼졌고, K-드라마와 예능 덕분에 외국 팬들도 ''daebak''으로 많이 안다.','오래전부터 쓰이던 말로, 영화계와 언론을 거쳐 일상어가 되었고 K-드라마로 해외에도 알려짐','좋은 소식이나 놀라운 일에 감탄할 때 쓴다. 어디서나 편하게 쓸 수 있다.',NULL,'{"sns": "green", "work": "green", "family": "green", "friends": "green"}'::jsonb,'[{"text": "대박! 진짜 축하해", "situation": "친구가 합격 소식을 전할 때"}, {"text": "여기 떡볶이 대박이다", "situation": "맛집에서"}]'::jsonb,'green','active','approved','phrase','text','beginner','wholesome',null,null,'unknown',NULL,46,now()) on conflict (slug) do nothing;
insert into memes (title,slug,aliases,summary,description,origin,usage_note,caution,usage_context,usage_examples,safety_level,lifecycle_status,moderation_status,category,media_type,difficulty,sentiment,origin_year,korea_viral_year,year_precision,era_type,trend_score,published_at) values ('막내','막내','{황금막내,"막내 온 탑",Maknae,maknae}'::text[],'집이나 그룹에서 가장 어린 사람','가족에서 가장 어린 자식, 또는 어떤 무리에서 나이가 가장 어린 사람을 뜻하는 순우리말이다. K-팝 그룹에서도 가장 어린 멤버를 막내라고 부르기 때문에 외국 팬들에게 ''maknae''로 널리 알려졌다. 노래, 춤, 운동을 다 잘하는 막내는 ''황금막내''라고 부른다. 막내는 몇 살이 되어도 가족에게 아기 취급을 받는다는 농담도 많다.','오래된 순우리말로, 2010년대 K-팝 팬 문화를 통해 ''maknae''라는 말이 세계에 알려짐','그룹이나 가족에서 가장 어린 사람을 부를 때 쓴다. 아이돌 이야기에 자주 쓴다.',NULL,'{"sns": "green", "work": "green", "family": "green", "friends": "green"}'::jsonb,'[{"text": "그 그룹 막내가 춤 제일 잘 춰", "situation": "아이돌 이야기"}, {"text": "우리 팀 막내 들어왔어요", "situation": "회사에서"}]'::jsonb,'green','active','approved','phrase','text','beginner','wholesome',null,2012,'unknown','social_media',38,now()) on conflict (slug) do nothing;
insert into memes (title,slug,aliases,summary,description,origin,usage_note,caution,usage_context,usage_examples,safety_level,lifecycle_status,moderation_status,category,media_type,difficulty,sentiment,origin_year,korea_viral_year,year_precision,era_type,trend_score,published_at) values ('멍때리기','멍때리기','{멍때리다,불멍,물멍,"멍때리기 대회","Space out",Bulmeong}'::text[],'아무 생각 없이 멍하니 있는 것','넋을 놓고 멍하니 한곳을 바라보며 쉬는 것을 말한다. 영어로는 ''space out''에 가깝다. 2014년부터 한국에서는 누가 가장 오래 멍하니 있는지 겨루는 ''멍때리기 대회''가 열리고 있고, 연예인이 참가해 우승하기도 했다. 2020년 무렵부터 캠핑 불을 보며 멍때리는 ''불멍'', 물을 보는 ''물멍'' 같은 말도 유행했다.','2014년 시작된 ''멍때리기 대회''로 널리 알려졌고, 2020년 무렵 ''불멍''·''물멍''으로 이어짐','잠깐 쉬고 싶을 때, 또는 캠핑이나 바다에서 편히 쉬는 모습을 말할 때 쓴다.',NULL,'{"sns": "green", "work": "green", "family": "green", "friends": "green"}'::jsonb,'[{"text": "오늘 밤은 불멍하면서 쉬자", "situation": "캠핑장에서"}, {"text": "미안, 잠깐 멍때렸어", "situation": "수업 중 딴생각할 때"}]'::jsonb,'green','active','approved','phrase','text','beginner','wholesome',2014,2014,'year','social_media',37,now()) on conflict (slug) do nothing;
insert into memes (title,slug,aliases,summary,description,origin,usage_note,caution,usage_context,usage_examples,safety_level,lifecycle_status,moderation_status,category,media_type,difficulty,sentiment,origin_year,korea_viral_year,year_precision,era_type,trend_score,published_at) values ('애교','애교','{Aegyo,aegyo,"애교 부리기"}'::text[],'귀여운 목소리나 몸짓으로 사랑스러움을 표현하는 것','귀여운 목소리, 말투, 표정, 손동작으로 사랑스럽게 구는 행동을 말한다. K-팝 아이돌이 예능이나 팬 사인회에서 애교를 보여 주는 장면이 많아 해외 팬들에게도 ''aegyo''로 알려졌다. 손으로 볼을 감싸거나 혀 짧은 소리를 내는 것이 대표적이다. 다만 특히 어린 여성에게 애교를 강요하는 문화에는 비판도 있다.','오래된 한국어 표현이 2010년대 K-팝 아이돌 예능과 팬 문화를 통해 세계에 ''aegyo''로 알려짐','친한 사이에서 장난스럽게 귀여운 척할 때, 또는 아이돌 영상 이야기를 할 때 쓴다.','누군가에게 "애교 좀 해 봐"라고 시키는 건 실례가 될 수 있다. 특히 성별에 따라 강요하지 말자.','{"sns": "green", "work": "gray", "family": "green", "friends": "green"}'::jsonb,'[{"text": "저 멤버 애교 진짜 자연스럽다", "situation": "아이돌 예능을 보며"}, {"text": "애교 부려도 숙제는 안 보여 줘", "situation": "친구가 부탁할 때"}]'::jsonb,'yellow','active','approved','phrase','video','beginner','wholesome',2010,2012,'approximate','social_media',39,now()) on conflict (slug) do nothing;
insert into memes (title,slug,aliases,summary,description,origin,usage_note,caution,usage_context,usage_examples,safety_level,lifecycle_status,moderation_status,category,media_type,difficulty,sentiment,origin_year,korea_viral_year,year_precision,era_type,trend_score,published_at) values ('엄근진','엄근진','{"엄격 근엄 진지","엄격 진지",Eom-geun-jin,Eomgeunjin}'::text[],'''엄격, 근엄, 진지''의 줄임말','별것 아닌 일에 지나치게 진지하고 엄격하게 구는 모습을 장난스럽게 말할 때 쓴다. 인터넷 커뮤니티의 만화에서 사소한 일로 벌점을 주는 엄숙한 인물들이 나온 장면에서 퍼졌다. 처음에는 과하게 따지는 사람을 놀리는 말이었지만, 지금은 "엄근진 모드"처럼 스스로 진지해질 때도 쓴다.','2014년 인터넷 커뮤니티의 ''엄격 진지'' 밈에 2015년 연재 만화에서 ''근엄''이 붙으며 완성되어 확산','농담 분위기에서 진지해진 사람을 가볍게 놀리거나, 나 스스로 진지해질 때 쓴다.','상대의 진지한 고민에 쓰면 무시하는 말로 들릴 수 있다.','{"sns": "green", "work": "yellow", "family": "green", "friends": "green"}'::jsonb,'[{"text": "왜 이렇게 엄근진이야", "situation": "친구가 게임 규칙을 너무 따질 때"}, {"text": "지금부터 엄근진 모드 들어간다", "situation": "시험 공부 시작할 때"}]'::jsonb,'yellow','cooling','approved','phrase','text','normal','ironic',2014,2015,'year','social_media',32,now()) on conflict (slug) do nothing;
insert into memes (title,slug,aliases,summary,description,origin,usage_note,caution,usage_context,usage_examples,safety_level,lifecycle_status,moderation_status,category,media_type,difficulty,sentiment,origin_year,korea_viral_year,year_precision,era_type,trend_score,published_at) values ('직관','직관','{"직접 관람",집관,직관러,Jikgwan}'::text[],'경기나 공연을 현장에 가서 직접 보는 것','''직접 관람''의 줄임말로, 야구나 축구 경기, 콘서트를 경기장이나 공연장에 직접 가서 보는 것을 말한다. 반대로 집에서 TV나 휴대폰으로 보는 것은 ''집관''이라고 한다. 한국 프로야구 응원 문화가 유명해지면서 외국인 관광객도 ''직관''을 하러 야구장에 많이 간다. 경기장에서 다 같이 응원가를 부르는 재미 때문에 집관보다 직관을 더 좋아하는 팬이 많다.','스포츠와 공연 팬 사이에서 ''직접 관람''을 줄여 쓰며 퍼진 말로, 정확한 유래는 알려져 있지 않음','경기나 공연을 보러 간다고 말할 때 쓴다. 야구, 축구, 콘서트 이야기에 잘 어울린다.',NULL,'{"sns": "green", "work": "green", "family": "green", "friends": "green"}'::jsonb,'[{"text": "토요일에 야구 직관 갈래?", "situation": "주말 계획"}, {"text": "이번엔 집관으로 만족해야겠다", "situation": "표를 못 구했을 때"}]'::jsonb,'green','active','approved','phrase','text','beginner','wholesome',null,2015,'unknown','social_media',39,now()) on conflict (slug) do nothing;
insert into memes (title,slug,aliases,summary,description,origin,usage_note,caution,usage_context,usage_examples,safety_level,lifecycle_status,moderation_status,category,media_type,difficulty,sentiment,origin_year,korea_viral_year,year_precision,era_type,trend_score,published_at) values ('치맥','치맥','{"치킨과 맥주",Chimaek,chimaek,맥치}'::text[],'치킨과 맥주를 함께 먹는 한국 문화','프라이드치킨과 맥주의 앞 글자를 딴 말이다. 둘 다 원래 한국 음식은 아니지만, 함께 즐기는 문화는 한국을 대표하는 것으로 여겨진다. 2002년 월드컵 때 응원하며 치맥을 많이 먹으면서 더 유명해졌다. 드라마 ''별에서 온 그대''의 치맥 장면 덕분에 중국어권에서도 크게 유행했다. 지금은 영어 위키백과에도 ''Chimaek''이라는 항목이 있다.','1990년대 호프집 안주 문화에서 자리 잡아, 2002년 월드컵과 드라마 ''별에서 온 그대''를 거치며 해외까지 확산','친구와 저녁 약속을 잡거나, 스포츠 경기를 함께 볼 때 쓴다.','술이 들어가는 문화라 미성년자나 술을 못 마시는 사람에게 강요하지 말자.','{"sns": "green", "work": "green", "family": "green", "friends": "green"}'::jsonb,'[{"text": "오늘 경기 보면서 치맥 어때?", "situation": "축구 경기가 있는 날"}, {"text": "이번 주 고생했으니 치맥 한잔하자", "situation": "퇴근길"}]'::jsonb,'green','active','approved','phrase','text','beginner','wholesome',2000,2002,'decade','early_web',47,now()) on conflict (slug) do nothing;
insert into memes (title,slug,aliases,summary,description,origin,usage_note,caution,usage_context,usage_examples,safety_level,lifecycle_status,moderation_status,category,media_type,difficulty,sentiment,origin_year,korea_viral_year,year_precision,era_type,trend_score,published_at) values ('파이팅','파이팅','{화이팅,Fighting,Hwaiting,"아자 파이팅"}'::text[],'''힘내!''라는 뜻의 한국식 응원 구호','영어 ''fighting''에서 왔지만, 한국에서는 "힘내", "잘해 보자"라는 뜻으로 쓰는 응원 구호다. 영어권에서는 ''싸움''이라는 뜻이라서 한국어를 모르는 사람은 이 뜻으로 알아듣지 못한다. 한국 드라마, 예능, K-팝 영상에 자주 나와서 외국 팬들도 많이 따라 한다. 주먹을 쥐고 팔을 들며 외치는 동작이 함께 쓰인다.','영어 ''fighting''이 한국에서 응원 구호로 바뀐 한국식 영어로, 스포츠 응원과 방송을 통해 널리 쓰임','시험, 경기, 발표를 앞둔 사람을 응원할 때 쓴다. 외국인 친구에게는 "힘내"라는 뜻이라고 함께 알려 주자.',NULL,'{"sns": "green", "work": "green", "family": "green", "friends": "green"}'::jsonb,'[{"text": "오늘 시험 파이팅!", "situation": "시험 보러 가는 친구에게"}, {"text": "이번 프로젝트 다 같이 파이팅", "situation": "팀 회의를 마치며"}]'::jsonb,'green','active','approved','phrase','text','beginner','wholesome',null,null,'unknown',NULL,40,now()) on conflict (slug) do nothing;
insert into memes (title,slug,aliases,summary,description,origin,usage_note,caution,usage_context,usage_examples,safety_level,lifecycle_status,moderation_status,category,media_type,difficulty,sentiment,origin_year,korea_viral_year,year_precision,era_type,trend_score,published_at) values ('할많하않','할많하않','{"할 말은 많지만 하지 않겠다",Hal-man-ha-an,Halmanhaan}'::text[],'''할 말은 많지만 하지 않겠다''의 줄임말','하고 싶은 말은 많지만 참고 넘어가겠다는 뜻이다. 대화가 안 통하는 상대와 더 말하고 싶지 않을 때, 길게 설명하는 대신 불편한 마음을 짧게 보여 줄 때 쓴다. 너무 어이없는 일을 보고 할 말을 잃었을 때도 쓴다. 스포일러를 피하려고 말을 아낄 때 쓰기도 한다. 말싸움에서 밀릴 때 슬쩍 빠져나가는 말로 쓰여 놀림을 받기도 한다.','2015년 후반 인터넷에서 생긴 신조어로 추정되며, 이후 SNS 댓글로 널리 퍼짐','어이없는 상황을 짧게 표현하거나, 말싸움을 끝내고 싶을 때 쓴다.','윗사람이나 진지한 대화에서 쓰면 비꼬는 말로 들릴 수 있다.','{"sns": "green", "work": "gray", "family": "yellow", "friends": "green"}'::jsonb,'[{"text": "오늘 회의… 할많하않", "situation": "황당한 일을 겪고 나서"}, {"text": "스포일러라서 할많하않", "situation": "드라마 결말을 묻는 친구에게"}]'::jsonb,'yellow','cooling','approved','phrase','text','beginner','ironic',2015,2016,'approximate','social_media',33,now()) on conflict (slug) do nothing;
insert into memes (title,slug,aliases,summary,description,origin,usage_note,caution,usage_context,usage_examples,safety_level,lifecycle_status,moderation_status,category,media_type,difficulty,sentiment,origin_year,korea_viral_year,year_precision,era_type,trend_score,published_at) values ('현타','현타','{"현실 자각 타임","현타 온다","현타 왔다",Hyeonta}'::text[],'''현실 자각 타임''의 줄임말, 갑자기 현실을 깨닫는 순간','꿈이나 기대에 빠져 있다가 내가 처한 진짜 상황을 갑자기 깨닫는 순간을 말한다. 열심히 하던 일이 갑자기 허무하게 느껴지거나, 내가 한 행동이 부끄러워질 때도 쓴다. 예를 들어 밤새 게임을 하다 아침 해를 보고 "현타 온다"라고 한다. 웃음 섞인 자기 고백으로 많이 쓰인다.','2010년대 인터넷 커뮤니티에서 ''현실 자각 타임''을 줄여 쓰기 시작해 일상어로 퍼짐','갑자기 허무해지거나 현실을 깨달은 순간을 웃으며 말할 때 쓴다.',NULL,'{"sns": "green", "work": "green", "family": "green", "friends": "green"}'::jsonb,'[{"text": "해 뜨는 거 보니까 현타 온다", "situation": "밤새 놀고 아침에"}, {"text": "쇼핑하고 잔액 보니 현타 왔어", "situation": "통장 잔액을 보고"}]'::jsonb,'green','active','approved','phrase','text','beginner','ironic',2014,2016,'approximate','social_media',38,now()) on conflict (slug) do nothing;
