insert into meme_translations (meme_id,locale,localized_slug,title,summary,description,origin,usage_note,caution,aliases,usage_examples,status,source_updated_at,provider,model,prompt_version,reviewed_at,reviewed_by) select m.id,'en','kkondae','Kkondae (꼰대): Condescending Know-It-All','A put-down for someone who lectures others','Once students'' slang for fathers and teachers. Now it means anyone, of any age, who is authoritarian and insists their experience is the only right way. The behavior is "kkondae-jil", and young ones are "young kkondae". In 2019 the BBC featured it as a word of the day and in an article.','Old student slang widened in the 2010s to mean any bossy person','Use it to criticize bossy behavior or check yourself.','It is a put-down; using it at work can start fights.','{Boomer,Know-it-all}'::text[],'[{"text": "Did I just sound like a kkondae?", "situation": "Checking yourself"}]'::jsonb,'reviewed',m.updated_at,'editorial','human',1,now(),(select id from profiles where role='operator' order by created_at limit 1) from memes m where m.slug='꼰대' on conflict (meme_id,locale) do nothing;
insert into meme_translations (meme_id,locale,localized_slug,title,summary,description,origin,usage_note,caution,aliases,usage_examples,status,source_updated_at,provider,model,prompt_version,reviewed_at,reviewed_by) select m.id,'en','kku-an-kku','Kku-an-kku (꾸안꾸): Effortlessly Styled','Short for "styled, but like you did not try"','A natural outfit or makeup that looks stylish without too much effort. Simple clothes with a careful touch are the key. It started as shopping-mall and magazine wording and became everyday talk. The opposite, fully dressed up, is "kku-kku-kku".','From late 2019 in Korean fashion shops, magazines and social media','Use it to praise a natural, stylish look.',NULL,'{"Effortless chic"}'::text[],'[{"text": "Your outfit is so kku-an-kku today.", "situation": "Complimenting a friend"}]'::jsonb,'reviewed',m.updated_at,'editorial','human',1,now(),(select id from profiles where role='operator' order by created_at limit 1) from memes m where m.slug='꾸안꾸' on conflict (meme_id,locale) do nothing;
insert into meme_translations (meme_id,locale,localized_slug,title,summary,description,origin,usage_note,caution,aliases,usage_examples,status,source_updated_at,provider,model,prompt_version,reviewed_at,reviewed_by) select m.id,'en','saved-in-my-heart','Saved in My Heart (내 마음속에 저장)','A cute way to say "I am keeping this in my heart"','Made famous in 2017 by Park Ji-hoon, who said it with a wink on the Mnet show "Produce 101 Season 2". People say it when they see a photo or moment they love.','2017 scene from Mnet Produce 101 Season 2','Use it playfully for things you love.',NULL,'{"Wink save"}'::text[],'[{"text": "Saved in my heart.", "situation": "Seeing a cute puppy photo"}]'::jsonb,'reviewed',m.updated_at,'editorial','human',1,now(),(select id from profiles where role='operator' order by created_at limit 1) from memes m where m.slug='내-마음속에-저장' on conflict (meme_id,locale) do nothing;
insert into meme_translations (meme_id,locale,localized_slug,title,summary,description,origin,usage_note,caution,aliases,usage_examples,status,source_updated_at,provider,model,prompt_version,reviewed_at,reviewed_by) select m.id,'en','nae-don-nae-san','Nae-don-nae-san (내돈내산): Bought With My Own Money','Means "I paid for it myself", a not-sponsored review tag','A tag for reviews of things you bought yourself, with no ad deal. As paid influencer reviews grew, creators started using it to show honest reviews, sometimes with receipts. Still, some use the tag while being paid, so it is not proof.','First used by a YouTuber around 2015, widespread by about 2020','Use it when reviewing something you bought.','Do not use it if you were paid. Hiding ads can break the law.','{"Not sponsored","Self-paid review"}'::text[],'[{"text": "Nae-don-nae-san, so this is my honest review.", "situation": "Posting a review"}]'::jsonb,'reviewed',m.updated_at,'editorial','human',1,now(),(select id from profiles where role='operator' order by created_at limit 1) from memes m where m.slug='내돈내산' on conflict (meme_id,locale) do nothing;
insert into meme_translations (meme_id,locale,localized_slug,title,summary,description,origin,usage_note,caution,aliases,usage_examples,status,source_updated_at,provider,model,prompt_version,reviewed_at,reviewed_by) select m.id,'en','noejeol','Noe-jeol (뇌절): Overdoing a Joke','Repeating the same joke until it kills the mood','From the Korean saying "only sing the first verse": past verse 1 and 2, you keep going too far. It sounds like a move name in the manga "Naruto", which made it a pun.','Spread in Korean online communities around 2019 as wordplay','Use it to stop a friend''s overused joke.','Can sound like a put-down. Keep it for close friends.','{"Overdoing it"}'::text[],'[{"text": "Stop, that is noe-jeol now.", "situation": "The fifth time the same joke"}]'::jsonb,'reviewed',m.updated_at,'editorial','human',1,now(),(select id from profiles where role='operator' order by created_at limit 1) from memes m where m.slug='뇌절' on conflict (meme_id,locale) do nothing;
insert into meme_translations (meme_id,locale,localized_slug,title,summary,description,origin,usage_note,caution,aliases,usage_examples,status,source_updated_at,provider,model,prompt_version,reviewed_at,reviewed_by) select m.id,'en','nunchi','Nunchi (눈치): Reading the Room','The sense of reading moods without being told','The ability to quickly sense other people''s feelings and the mood of a room. It matters a lot in Korean relationships, as in "fast nunchi" or "get some nunchi". English has no exact word, so it is often compared to emotional intelligence.','An old Korean word, introduced abroad as a cultural concept from the 2010s','Use it to praise someone who reads the room well.','Saying someone "has no nunchi" can be a put-down.','{"Reading the room"}'::text[],'[{"text": "Using my nunchi, I will head out first.", "situation": "Leaving two friends alone"}]'::jsonb,'reviewed',m.updated_at,'editorial','human',1,now(),(select id from profiles where role='operator' order by created_at limit 1) from memes m where m.slug='눈치' on conflict (meme_id,locale) do nothing;
insert into meme_translations (meme_id,locale,localized_slug,title,summary,description,origin,usage_note,caution,aliases,usage_examples,status,source_updated_at,provider,model,prompt_version,reviewed_at,reviewed_by) select m.id,'en','daebak','Daebak (대박): Awesome! / No Way!','Said when something is a huge hit or amazing','Used when something is a big success or surprisingly great: "daebak nasseo" (it was a hit). A smaller win is "jungbak", a flop is "jjokbak". It likely comes from gambling slang for winning big. The film industry and the press spread it, and K-dramas made it known to fans worldwide.','An old word spread by the film industry and media, known abroad through K-dramas','Use it to react to great news or something amazing.',NULL,'{Awesome,Jackpot}'::text[],'[{"text": "Daebak! Congrats!", "situation": "A friend got accepted"}]'::jsonb,'reviewed',m.updated_at,'editorial','human',1,now(),(select id from profiles where role='operator' order by created_at limit 1) from memes m where m.slug='대박' on conflict (meme_id,locale) do nothing;
insert into meme_translations (meme_id,locale,localized_slug,title,summary,description,origin,usage_note,caution,aliases,usage_examples,status,source_updated_at,provider,model,prompt_version,reviewed_at,reviewed_by) select m.id,'en','maknae','Maknae (막내): The Youngest','The youngest person in a family or group','A native Korean word for the youngest child, or the youngest member of any group. K-pop groups call their youngest member the maknae, so global fans know it well. A maknae who is great at everything is the "golden maknae". Jokes say the maknae is treated like a baby forever.','An old Korean word made global through 2010s K-pop fandom','Use it for the youngest member of a group or family.',NULL,'{"Golden maknae",Youngest}'::text[],'[{"text": "The maknae is the best dancer.", "situation": "Talking about an idol group"}]'::jsonb,'reviewed',m.updated_at,'editorial','human',1,now(),(select id from profiles where role='operator' order by created_at limit 1) from memes m where m.slug='막내' on conflict (meme_id,locale) do nothing;
insert into meme_translations (meme_id,locale,localized_slug,title,summary,description,origin,usage_note,caution,aliases,usage_examples,status,source_updated_at,provider,model,prompt_version,reviewed_at,reviewed_by) select m.id,'en','meongttaerigi','Meongttaerigi (멍때리기): Spacing Out','Zoning out and thinking about nothing','Resting while staring blankly, like "spacing out". Since 2014, Korea has held a "Space-Out Competition" to see who can zone out longest. Around 2020, "bulmeong" (staring at a campfire) and "mulmeong" (at water) became popular.','Known through the space-out competition held since 2014, then bulmeong around 2020','Use it when you want a break or describe relaxing by fire or water.',NULL,'{"Space out",bulmeong}'::text[],'[{"text": "Tonight we do bulmeong and relax.", "situation": "At a campsite"}]'::jsonb,'reviewed',m.updated_at,'editorial','human',1,now(),(select id from profiles where role='operator' order by created_at limit 1) from memes m where m.slug='멍때리기' on conflict (meme_id,locale) do nothing;
insert into meme_translations (meme_id,locale,localized_slug,title,summary,description,origin,usage_note,caution,aliases,usage_examples,status,source_updated_at,provider,model,prompt_version,reviewed_at,reviewed_by) select m.id,'en','aegyo','Aegyo (애교): Acting Cute','Showing affection with a cute voice, face or gestures','Acting cute with a baby-like voice, expressions or hand gestures. K-pop idols often do it on variety shows and at fan meetings, so global fans know it as "aegyo". There is also criticism of expecting it, especially from young women.','An old Korean word made global through 2010s K-pop variety shows','Use it playfully among close friends or when talking about idols.','Asking someone to "do aegyo" can be rude, especially based on gender.','{"Acting cute"}'::text[],'[{"text": "That member''s aegyo looks so natural.", "situation": "Watching an idol show"}]'::jsonb,'reviewed',m.updated_at,'editorial','human',1,now(),(select id from profiles where role='operator' order by created_at limit 1) from memes m where m.slug='애교' on conflict (meme_id,locale) do nothing;
insert into meme_translations (meme_id,locale,localized_slug,title,summary,description,origin,usage_note,caution,aliases,usage_examples,status,source_updated_at,provider,model,prompt_version,reviewed_at,reviewed_by) select m.id,'en','eom-geun-jin','Eom-geun-jin (엄근진): Strict, Stern, Serious','Short for "strict, stern, serious"','A playful way to call out someone being way too serious about small things. It spread from a Korean forum comic where stern characters hand out penalty stickers for trivial things. Now people also say "eom-geun-jin mode" about themselves.','A 2014 forum meme completed by a 2015 web comic','Use it to tease someone who got too serious, or yourself.','Do not use it on someone''s real worries.','{"Too serious"}'::text[],'[{"text": "Why so eom-geun-jin?", "situation": "A friend obsesses over game rules"}]'::jsonb,'reviewed',m.updated_at,'editorial','human',1,now(),(select id from profiles where role='operator' order by created_at limit 1) from memes m where m.slug='엄근진' on conflict (meme_id,locale) do nothing;
insert into meme_translations (meme_id,locale,localized_slug,title,summary,description,origin,usage_note,caution,aliases,usage_examples,status,source_updated_at,provider,model,prompt_version,reviewed_at,reviewed_by) select m.id,'en','jikgwan','Jikgwan (직관): Watching It Live','Going to see a game or show in person','Short for "watching directly": going to the stadium or concert hall. Watching at home is "jipgwan". As Korean baseball cheering got famous, many tourists go for jikgwan.','Shortened by sports and concert fans; exact origin unknown','Use it when you go to a game or concert.',NULL,'{"Watching live",jipgwan}'::text[],'[{"text": "Want to do baseball jikgwan on Saturday?", "situation": "Weekend plans"}]'::jsonb,'reviewed',m.updated_at,'editorial','human',1,now(),(select id from profiles where role='operator' order by created_at limit 1) from memes m where m.slug='직관' on conflict (meme_id,locale) do nothing;
insert into meme_translations (meme_id,locale,localized_slug,title,summary,description,origin,usage_note,caution,aliases,usage_examples,status,source_updated_at,provider,model,prompt_version,reviewed_at,reviewed_by) select m.id,'en','chimaek','Chimaek (치맥): Fried Chicken and Beer','Fried chicken and beer, a classic Korean pairing','From "chikin" (fried chicken) and "maekju" (beer). Neither is Korean food, but enjoying them together is seen as Korean culture. It grew during the 2002 World Cup, and the drama "My Love from the Star" made it a craze in Chinese-speaking regions.','Korean pub culture in the 1990s, boosted by the 2002 World Cup and K-dramas','Use it when making evening plans or watching sports.','Do not pressure minors or non-drinkers to drink.','{"Chicken and beer"}'::text[],'[{"text": "Chimaek while we watch the match?", "situation": "On game day"}]'::jsonb,'reviewed',m.updated_at,'editorial','human',1,now(),(select id from profiles where role='operator' order by created_at limit 1) from memes m where m.slug='치맥' on conflict (meme_id,locale) do nothing;
insert into meme_translations (meme_id,locale,localized_slug,title,summary,description,origin,usage_note,caution,aliases,usage_examples,status,source_updated_at,provider,model,prompt_version,reviewed_at,reviewed_by) select m.id,'en','fighting','Hwaiting / Fighting (파이팅): You Can Do It!','A Korean cheer meaning "go for it!"','From English "fighting", but in Korea it means "cheer up" or "let''s do this". English speakers hear "fighting" as combat, so it confuses people who do not know Korean. It appears often in K-dramas and K-pop videos, usually with a raised fist.','Konglish cheer used in Korean sports and TV','Use it to cheer someone before a test, game or talk.',NULL,'{Hwaiting,Fighting}'::text[],'[{"text": "Exam today? Hwaiting!", "situation": "A friend heads to an exam"}]'::jsonb,'reviewed',m.updated_at,'editorial','human',1,now(),(select id from profiles where role='operator' order by created_at limit 1) from memes m where m.slug='파이팅' on conflict (meme_id,locale) do nothing;
insert into meme_translations (meme_id,locale,localized_slug,title,summary,description,origin,usage_note,caution,aliases,usage_examples,status,source_updated_at,provider,model,prompt_version,reviewed_at,reviewed_by) select m.id,'en','halmanhaan','Hal-man-ha-an (할많하않): Much to Say, Not Saying It','Short for "I have a lot to say, but I won''t"','You hold back the many things you want to say. Used when a talk is going nowhere, to show annoyance briefly, or when something is too absurd for words. Also used to avoid spoilers.','Thought to have appeared online in late 2015, spread via social media comments','Use it to react briefly to absurd things.','Can sound sarcastic in serious talks or with seniors.','{"No comment"}'::text[],'[{"text": "Today''s meeting... hal-man-ha-an.", "situation": "After a messy meeting"}]'::jsonb,'reviewed',m.updated_at,'editorial','human',1,now(),(select id from profiles where role='operator' order by created_at limit 1) from memes m where m.slug='할많하않' on conflict (meme_id,locale) do nothing;
insert into meme_translations (meme_id,locale,localized_slug,title,summary,description,origin,usage_note,caution,aliases,usage_examples,status,source_updated_at,provider,model,prompt_version,reviewed_at,reviewed_by) select m.id,'en','hyeonta','Hyeon-ta (현타): Reality Check Moment','Short for "reality-awareness time"','The moment you suddenly see your real situation after being lost in a dream or hype. It also means feeling empty about something you were into, or embarrassed about what you did, like seeing sunrise after gaming all night.','Shortened from "reality-awareness time" on Korean forums in the 2010s','Use it to joke about a sudden reality check.',NULL,'{"Reality check"}'::text[],'[{"text": "Saw my balance. Hyeon-ta hit.", "situation": "Checking your bank balance after shopping"}]'::jsonb,'reviewed',m.updated_at,'editorial','human',1,now(),(select id from profiles where role='operator' order by created_at limit 1) from memes m where m.slug='현타' on conflict (meme_id,locale) do nothing;
